SELECT 
FROM asset_item

    deleted_dttm IS NULL

        AND (name LIKE CONCAT('%', #{keyword}, '%')
            OR storage_location LIKE CONCAT('%', #{keyword}, '%'))


        AND category_code = #{categoryCode}


        AND tracking_type_code = #{trackingType}


        AND status_code = #{status}


ORDER BY name, asset_item_id

mapper.insert:
INSERT INTO asset_item (
    name, category_code, tracking_type_code, owner_type_code,
    owner_member_id, external_owner_name, total_quantity,
    storage_location, status_code, photo_file_id, note
) VALUES (
    #{name}, #{categoryCode}, #{trackingType}, #{ownerType},
    #{ownerMemberId}, #{externalOwnerName}, #{totalQuantity},
    #{storageLocation}, #{status}, #{photoFileId}, #{note}
)

INSERT INTO asset_unit (
    asset_item_id, management_no, status_code, storage_location
) VALUES (
    #{assetItemId}, #{managementNo}, #{status}, #{storageLocation}
)

INSERT INTO asset_history (
    asset_item_id, asset_unit_id, action_code, quantity,
    previous_status_code, new_status_code, note,
    changed_by_member_id, changed_dttm
) VALUES (
    #{assetItemId}, #{assetUnitId}, #{action}, #{quantity},
    #{previousStatus}, #{newStatus}, #{note},
    #{changedByMemberId}, #{changedDttm}
)

